def Q_test(k3):
    return 64 * k3**3 - 499 * k3 + 3402

# Check integer roots up to |k3| = 20, since the divisors of 3402 are manageable
print("Checking roots in [-20, 20]:")
found = False
for k3 in range(-20, 21):
    result = Q_test(k3)
    if result == 0:
        print(f"SUCCESS: Integer root found at k3 = {k3}. Q({k3}) = 0.")
        found = True
        break
if not found:
    print("FAILURE: No integer root found in the tested range.")
